"""Measured primitive contract and maintained source locks; no self-promotion."""
import argparse,hashlib,json,re,sys
from datetime import date
from closure_support import ROOT,save
from render_primitives_shells import OUT,FILES,NAMES,SOURCES
from render_primitives_proofs import jobs,current
sys.path.insert(0,str(ROOT/'tools'))
import closure

def evidence(prop,level,command,result,method):return dict(property=prop,level=level,command=command,result=result,method=method,date=date.today().isoformat())
def read(name):return json.loads((OUT/name).read_text())
def main():
    ap=argparse.ArgumentParser();ap.add_argument('--draft',action='store_true');a=ap.parse_args()
    inventory=read('inventory.json');symbols=(ROOT/'c/ugh_sym.h').read_text();files=[p.relative_to(ROOT).as_posix() for p in FILES]
    c=dict(component='render_primitives',status='unanalyzed',proposed_status='boundary-established',
      original=dict(owned=[dict(identity='GAME:'+n,address='013B:'+re.search(r'#define UGH_O_GAME_'+n+r' 0x([0-9A-Fa-f]+)u',symbols)[1],l1='c_'+n) for n in NAMES],l1=['c/render.c','c/render_primitives.c']),
      native=dict(files=files,header=files[0],functions=['render_sprite_place','render_sprite_begin','render_sprite_pixel','render_sprite_column','render_rectangle','render_next_row','render_save','render_map_tile','render_map_cell','render_tile_rectangle','render_playfield_rectangle','render_sprite_rectangle','render_restore_sprite_index','render_player_visible','render_player_restore','render_player_animation','render_cache_store'],build='python verif/render_primitives_build.py'),
      purpose='Decide ordered sprite, map, background copy/restore and player-animation requests over borrowed resources and canonical rendering caches. Keep the physical VGA operations as precise synchronous services.',
      interface=dict(inputs=['Raw16-bit sprite IDs, signed coordinates/height/surface and all wrapping page/resource cell words; all dimensions bytes including zero; arbitrary source bytes, incoming DF and inherited VGA controls.','Selected physical player0/2 animation/countdown/rate/cycle words and current/cached sprite/pixel words. No phase, initialization or finite-delay restriction. Cache-copy entry retains arbitrary wrapping index and ordered reads.','Full pointer segments remain backend bindings: water/page selection uses existing pointers exactly; sprite and rectangle output deliberately use physical A000 with page offsets only.'],outputs=['Ordered native placement, metadata index/bank, masks and per-byte draw/skip decisions; rectangle row-copy requests and exact REP endpoints.','Ordered selected-player animation stores and conditional draw/restore, followed by the original cache tail. Matching cuts consume the native value before each real service.'],effects=inventory['retained_services'],preconditions=['Ordinary disjoint code/data, stack and borrowed resources. Pixel services are synchronous and do not mutate player simulation/caches or resource descriptors while the primitive executes.','One selected physical player0/2 for animation/restore native projection; malformed indices retain the full literal shell. No clipping or safe-pointer promise for malformed resources.','Scalar native cursor continuations are constructed by the initializer; byte row/column counters use do/decrement semantics. Source direction is Boolean in normal construction. All arithmetic kernels additionally admit arbitrary scalar words/bytes.']),
      callers=inventory['callers'],callees=dict(native=['render_primitives API'],services=['VGA sequencer/graphics-controller port transactions and live aperture reads/writes','DrawTransparentSprite from map/player wrappers','RestoreBackgroundRectangle from restore wrappers; CachePlayerDrawState immediate tail']),
      indirect=dict(targets=['Existing dispatch to DrawTransparentSprite, RestoreBackgroundRectangle, CachePlayerDrawState and DrawMapTile'],classification='Named original near calls/tails, with exact saved words and returns; no new indirect callback or session body.'),
      memory=dict(owned=['Working rendering requests/cursors only; player cached sprite/pixel arrays and animation updates project to their existing persistent arrays. No second image, player or water owner.','RendererScratchWord and SpritePlaneStateScratch remain the existing code-segment scratch words.'],borrowed=['Sprite directory, four pixel banks, map pointer/data, playfield/surface Y, pages/copy count and live VGA latch/control state. Current player motion/thrust state remains with its accepted owner.'],cache_writers=inventory['cache_writers'],projection='Animation stores consumed in order with matching selected field/address and value before draw; restore request consumed before immediate sprite tail, then cache tail reads live values in original order. Existing migrated actor/demo/water request streams and bridges are unchanged; dispatch resolves their original service entries to this module.'),
      assumptions=['B normalizes ordinary resource/selected-slot RAM; all16-bit scalar boundaries remain symbolic. Service pixel values and read results are arbitrary at the cut, with resource/stack frames.','B is split by actual C branch structure as listed in coverage. Other native bytes, padding and inactive cursor inputs have separate properties. Save-copy endpoint uses the actual REP base and one-step invariant, not a bounded whole-page proof.','Full RAM, device state, exact register/defined-flag ABI, service prefix and session composition have independent C/D evidence. No formal claim about arbitrary malformed overlapping machine resources or the VGA controller internals.'],
      eliminated=['Ordinary native code contains no machine registers, memory accessors, ports, segments, stack layout or dispatch.','Pixel byte selection and where/how much to draw/copy/restore come from native results; the bridge checks and consumes them. Native-only value/selection changes are mutation controls.'],
      retained=['No sprite clipping; signed Y>=PlayfieldHeight selects fixed page and subtracts192, irrespective of the height value. X uses SAR2. Directory index and page/source/destination additions wrap as words; banks compare IDs unsigned at217/298/547.','Zero sprite dimension bytes mean256, unlike rectangle restore where width remains the wrapped whole-cell formula and zero height means65536 rows. Transparent zero performs no destination read or write. Water equality==height does not shade; threshold0 shades rows only after the first. Shade OR40h happens only for a nonzero source.','Rectangle restore copies whole cells without edge masking, clears DF on every row, uses physical A000 and page offsets, sets write mode1 while preserving other GC5 bits, then clears only write-mode bits. Reads refresh live latches; do not substitute snapshot memcpy.','Save honors full page segments, incoming DF, raw count including zero, and individual word wrapping. It retains read/write ordering for overlaps and inherited plane/read/write controls.','RestoreSpriteBackground discards the loaded directory offset before reading raw dimensions from id*4. DrawTileMap leaves DS as the map resource segment, so sprite water reads use that live segment.','Player signed visibility uses strict x>-32,y>-20 and x<320,y<192. Rate caps only when signed>90; negative raw rates remain negative. Wrapped countdown<0 adds200 once and advances once, with signed cycle-end compare. Cache copying is three ordered source reads/stores, including malformed wrapping indices.'],
      evidence=[evidence('Checked inventory','B','python verif/render_primitives_inventory.py','PASS',inventory['composition'])],
      amiga=dict(classification='Meaning only',finding='DOS four-plane wrapping/latch transactions and its raw dimensions, water shade, cache timing and animation arithmetic are authoritative. No Amiga pixel/timing equivalence is claimed.'),
      uncertainty=['Only supervisor review changes administrative status. Existing actor_render/demo/water certificates and request streams are not edited.','B covers the declared native decisions and branch-stage seams; physical transactions and whole-session composition remain C/D.'],
      coverage=inventory['stages'],dependencies={n:closure.actual_dependencies(ROOT/n) for n in files})
    if not a.draft:
        matrix=read('proof-matrix.json');assert matrix['result']=='PASS'
        for key,mode in jobs():
            path=OUT/'proofs'/(key+'-'+mode)/'result.json';assert current(path);j=json.loads(path.read_text());assert j['peak_private_bytes']<=8*1024**3 and j['seconds']<=600
            e=evidence(key+' '+mode,'B','python verif/render_primitives_proof.py '+key+' '+mode,'PASS',inventory['composition']);e['profile']={k:j[k] for k in ['unwind','preprocessed_sha256','seconds','peak_private_bytes','hard_private_limit_bytes']};e['profile']['receipt']=str(path.relative_to(ROOT));c['evidence'].append(e)
        reach=read('reachability.json');assert len(reach)==15 and all(j['passed'] for j in reach)
        cases=read('cases/result.json');assert cases['result']=='PASS';mutants=read('mutants.json');assert len(mutants)==12 and all(j['result']=='DETECTED_BY_BRIDGE' for j in mutants)
        integration=read('integration.json');assert integration['whole_status']==0 and not any(j['problems'] for j in integration['cases']) and all(not any(j['fallbacks']) for j in integration['scenario_audits'])
        host=read('host.json');assert host['result']=='PASS' and host['check']['passed']
        c['evidence'] += [evidence('Full scalar slices','C','python verif/render_primitives_cases.py',cases['stdout'].strip(),cases['scope']),evidence('Consumption mutants','C','python verif/render_primitives_mutants.py','PASS12/12 DETECTED_BY_BRIDGE','Private native requests changed; original consuming ABI shell must reject. Compiler failures never count.'),evidence('L0/RAM/device and whole scenarios','D','python verif/render_primitives_integration.py --whole --local-reference','PASS',str(len(integration['cases']))+' complete routine comparisons;20 maintained scenarios plus rainy witness; all entry counts and zeros attached.'),evidence('Scratch actual promotion','D','python verif/render_primitives_host.py','PASS','Unchanged closure/build/native check on committed baseline plus owned files only;20 scenarios and smoke.')]
        c['scenario_entry_counts']=integration['scenario_audits'];c['entry_order']=NAMES;c['scratch_acceptance']=dict(baseline=host['baseline_revision'],linked_units=[u['component'] for u in host['build']['linked_units']]);c['proposed_status']='migrated'
        c['negative_results']=dict(reachability='15/15 deliberately false end-of-comparison assertions fail as required; see reachability.json.',ordinary=[dict(receipt=str(p.relative_to(ROOT)),result=j['result'],command=j['command']) for p in sorted((OUT/'negative').glob('*/result.json')) for j in [json.loads(p.read_text())] if j['result'] not in ['FAIL']])
        locked=[*FILES,*sorted((ROOT/'verif').glob('render_primitives*')),*sorted((ROOT/'c').glob('*.[ch]')),*sorted((ROOT/'tests/scenarios').glob('*.txt')),*[ROOT/'tests'/f'{n}.py' for n in ['actors_states','items_water','render','render_primitives','scene','menu','demo_scripts']],ROOT/'verif/water_weather_l0_cases.py',ROOT/'verif/random_rain.txt',ROOT/'metadata/verif-tools.json',ROOT/'verif/closure_support.py',ROOT/'verif/windows_job.py',ROOT/'verif/contacts_reference.py',*[ROOT/'tools'/n for n in ['closure.py','nbuild.py','hostbuild.py','wholegame.py','emu.py','difftest.py']],ROOT/'host/check.py']
        c['verification_input_hashing']='sha256-lf-text';c['verification_inputs']={p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes().replace(b'\r\n',b'\n')).hexdigest() for p in locked if p.is_file()}
    save(ROOT/'metadata/closure/render_primitives.json',c)
if __name__=='__main__':main()
